<script setup lang="ts">
import { benefitText } from '@/shared/i18n'
import {vDialogFocus} from './dialog-focus'
import {computed,ref,watch} from 'vue'
import {ArrowRight,Activity,Check,AlertTriangle,X,Landmark,Network,ShieldCheck,Wallet,Users,ChevronRight} from 'lucide-vue-next'
import {advance,acknowledge,requestBatch,summarize,statuses,type Scenario} from './live-engine'
import {data,num,money} from './data'
import MetricValue from './MetricValue.vue'
const state=ref(requestBatch()),scenario=ref<Scenario>('normal'),filter=ref('all'),region=ref(''),selected=ref<number|null>(null)

const agencies=['IHMA','Pensiya jamg‘armasi','Yoshlar jamg‘armasi','Ayollar jamg‘armasi','Bandlik jamg‘armasi']
const nodes=[{name:'Idora yubordi',icon:Landmark},{name:'Format tekshiruvi',icon:Network},{name:'Takroriylik tekshiruvi',icon:ShieldCheck},{name:'Ijro tasdig‘i',icon:Wallet},{name:'Fuqaro kabineti',icon:Users}]
const scope=computed(()=>state.value.events.filter(x=>region.value===''||x.region===+region.value))
const summary=computed(()=>summarize(scope.value))
const visible=computed(()=>scope.value.filter(x=>filter.value==='all'||x.status===filter.value).slice(-8).reverse())
const selectedEvent=computed(()=>state.value.events.find(x=>x.id===selected.value))
const reached=computed(()=>nodes.map((_,i)=>scope.value.filter(x=>x.stage>=i).length))

const regionCounts=computed(()=>data.regions.map((name,i)=>({name,i,...summarize(state.value.events.filter(e=>e.region===i))})))
const recordLabel=(id:number)=>'SR-'+String(id).padStart(5,'0')
watch(scenario, value=>{state.value=requestBatch(value);selected.value=null})
function confirmExecution(id:number){state.value=advance(acknowledge(state.value,id),scenario.value,false)}
const reason=computed(()=>selectedEvent.value?.status==='duplicate'?'Shaxs + chora + davr + manba hodisasi avval qayd etilgan. Qayta moliyaviy hisob yaratilmaydi.':selectedEvent.value?.status==='returned'?'Chora kodi yoki majburiy maydon yo‘q. Xabar manba idoraga tuzatish uchun qaytarildi.':selectedEvent.value?.status==='waiting'?'Ijro natijasi bo‘yicha idora tasdig‘i kutilmoqda. Hali yakunlangan xizmat sifatida hisoblanmagan.':selectedEvent.value?.status==='delivered'?'Tasdiqlangan ijro oila tarixiga yozildi. Bir hodisa bir marta hisobga olindi.':'Xabar tekshiruv bosqichlaridan o‘tmoqda.')
</script>
<template><section class="live-ops"><Teleport defer to="#support-filter-fields"><label>{{ benefitText("Hudud") }}<select v-model="region"><option value="">{{ benefitText("Respublika") }}</option><option v-for="item in regionCounts" :key="item.i" :value="String(item.i)">{{ benefitText(item.name) }}</option></select></label><label>{{ benefitText("Xabar holati") }}<select v-model="filter"><option value="all">{{ benefitText("Barcha holatlar") }}</option><option v-for="item in statuses" :key="item.key" :value="item.key">{{ benefitText(item.label) }}</option></select></label></Teleport><header><div><h2>{{ benefitText("Idoralararo xabarlar") }}</h2><p>{{ benefitText("Namunaviy ma’lumot") }}</p></div></header><Teleport defer to="#support-filter-fields"><div class="live-scenarios"><span>{{ benefitText("Xabar turi") }}</span><button v-for="[key,label] in [['normal','Asosiy holat'],['duplicates','Takroriy so‘rovlar'],['invalid','Ma’lumoti xato so‘rovlar'],['delay','Ijro tasdig‘i kechikkan']]" :key="key" :aria-pressed="scenario===key" @click="scenario=key as Scenario">{{ benefitText(label) }}</button></div></Teleport><div class="live-metrics"><button :class="{selected:filter==='all'}" @click="filter='all'"><small>{{ benefitText("Kelgan xabarlar") }}</small><strong><MetricValue :value="summary.received"/></strong><span>{{ benefitText("Tanlangan hududdagi jami") }}</span></button><button v-for="item in statuses" :key="item.key" :class="[item.color,{selected:filter===item.key}]" @click="filter=filter===item.key?'all':item.key"><small>{{ benefitText(item.label) }}</small><strong><MetricValue :value="summary[item.key]"/></strong><span>{{ benefitText(summary.received?num(summary[item.key]/summary.received*100,1):0) }}% <ChevronRight :size="12"/></span></button></div><div class="live-workspace"><div class="live-process"><div class="live-subhead"><h3>{{ benefitText("Xabarning harakati") }}</h3><span>{{ num(summary.deliveredAmount) }}{{ benefitText(" so‘m") }}</span></div><div class="live-nodes"><div v-for="(node,i) in nodes" :key="node.name" :class="{active:reached[i]}" class="live-node"><span class="live-node-icon"><component :is="node.icon" :size="23"/></span><h4>{{ benefitText(node.name) }}</h4><strong><MetricValue :value="reached[i]??0"/></strong><small>{{ benefitText("ta so‘rov") }}</small><div v-if="i<4" class="live-wire"><i v-if="reached[i]" :key="state.tick"></i></div></div></div><div class="live-outcomes"><div class="positive"><Check :size="18"/><span>{{ benefitText("Tasdiqlangan summa") }}<strong>{{ benefitText(money(summary.deliveredAmount)) }}{{ benefitText(" so‘m") }}</strong></span></div><div class="warning"><ShieldCheck :size="18"/><span>{{ benefitText("Takroriy xabarlar summasi") }}<strong>{{ benefitText(money(summary.duplicateAmount)) }}{{ benefitText(" so‘m") }}</strong></span></div></div><div class="live-region-head"><h3>{{ benefitText("14 hudud kesimi") }}</h3><button v-if="region!==''" @click="region=''">{{ benefitText("Respublikaga qaytish ×") }}</button><span v-else>{{ benefitText(summary.regions) }}{{ benefitText(" hududdan xabar bor") }}</span></div><div class="live-regions"><button v-for="item in regionCounts" :key="item.i" :class="{selected:region===String(item.i),}" @click="region=region===String(item.i)?'':String(item.i)"><span>{{ benefitText(benefitText(item.name).replace(' viloyati','').replace(' Respublikasi','')) }}</span><b>{{ benefitText(item.received) }}</b><i><em :style="{width:item.received?item.delivered/item.received*100+'%':'0%'}"/></i></button></div></div><section class="live-feed"><div class="live-subhead"><h3>{{ benefitText("Hodisalar lentasi") }}</h3><span>{{ benefitText(filter==='all'?'Oxirgi 8 xabar':statuses.find(x=>x.key===filter)?.label) }}</span></div><TransitionGroup name="live-event" tag="div" class="live-events"><button v-for="event in visible" :key="event.id" @click="selected=event.id"><span class="event-icon" :class="event.status"><component :is="event.status==='delivered'?Check:event.status==='duplicate'||event.status==='returned'?AlertTriangle:Activity" :size="15"/></span><div><strong>{{ benefitText(agencies[event.agency]) }}</strong><small>{{ benefitText(benefitText(data.regions[event.region]).replace(' viloyati','')) }} · {{ benefitText(recordLabel(event.id)) }}</small><span class="event-status" :class="event.status">{{ benefitText(statuses.find(x=>x.key===event.status)?.label) }}</span></div><b>{{ benefitText(event.amount?money(event.amount):event.kind==='service'?'Xizmat':'Imtiyoz') }}<small>{{ benefitText(statuses.find(s=>s.key===event.status)?.label) }}</small></b></button></TransitionGroup><p v-if="!visible.length" class="live-empty">{{ benefitText("Bu tanlovda hali hodisa yo‘q.") }}</p><p class="live-feed-note"></p></section></div><div v-if="selectedEvent" class="np-overlay" @click.self="selected=null" @keydown.esc="selected=null"><section class="np-dialog" v-dialog-focus role="dialog" aria-modal="true" aria-labelledby="live-event-title" tabindex="-1"><header><div><p class="live-eyebrow">{{ benefitText("SO‘ROV TAFSILOTLARI") }}</p><h2 id="live-event-title">{{ benefitText(recordLabel(selectedEvent.id)) }}</h2></div><button :aria-label="benefitText('So‘rov tafsilotlarini yopish')" @click="selected=null"><X :size="20"/></button></header><div class="live-detail-summary"><span>{{ benefitText(agencies[selectedEvent.agency]) }}</span><b>{{ benefitText(data.regions[selectedEvent.region]) }}</b><strong>{{ benefitText(selectedEvent.amount?num(selectedEvent.amount)+' so‘m':selectedEvent.kind==='service'?'Xizmat ko‘rsatish':'Imtiyozdan foydalanish') }}</strong><span :class="['event-status',selectedEvent.status]">{{ benefitText(statuses.find(x=>x.key===selectedEvent?.status)?.label) }}</span></div><p class="live-reason">{{ benefitText(reason) }}</p><ol class="live-detail-stages"><li v-for="(node,i) in nodes" :key="node.name" :class="{passed:i<=selectedEvent.stage}"><span>{{ benefitText(i<=selectedEvent.stage?'✓':i+1) }}</span><b>{{ benefitText(node.name) }}</b><small>{{ benefitText(i<selectedEvent.stage?'O‘tgan':i===selectedEvent.stage?statuses.find(x=>x.key===selectedEvent?.status)?.label:'Navbatda') }}</small></li></ol><button v-if="selectedEvent.status==='waiting'" class="live-primary" @click="confirmExecution(selectedEvent.id)">{{ benefitText("Javobni qayd etish ") }}<ArrowRight :size="15"/></button><p class="live-feed-note"></p></section></div></section></template>
<style scoped>
