;top:24px;background:#e2eaf7}.live-wire i{position:absolute;width:14px;height:6px;top:-2px;background:#467ee2;border-radius:6px;animation:livePacket .8s linear infinite}.live-outcomes{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:22px}.live-outcomes>div{display:flex;gap:10px;align-items:center;padding:12px;border:1px solid #dceee7;border-radius:8px;background:#f3faf7;color:#309b7c}.live-outcomes>.warning{border-color:#f0e4c9;background:#fffbf1;color:#bd944b}.live-outcomes span{font-size:11px;line-height:1.6}.live-outcomes strong{font-size:15px;display:block;font-weight:700}.live-outcomes svg{flex-shrink:0}.live-regions{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:12px}.live-regions button{display:flex;justify-content:space-between;align-items:center;gap:6px;padding:10px 8px 13px;border:1px solid var(--border);border-radius:7px;position:relative;overflow:hidden;background:var(--card);transition:background .2s,border-color .2s;text-align:left}.live-regions span{font-size:11px;color:var(--muted-foreground)}.live-regions b{font-size:13px;color:#597caf}.live-regions button>i{position:absolute;bottom:0;left:0;right:0;height:3px;background:#f1f5fb}.live-regions em{height:100%;display:block;background:#63bea6;transition:width .4s}.live-regions button.selected{border-color:#739fe5;background:#edf4ff}.live-regions button.pulse{animation:regionArrival 1s ease-out}.live-feed{border-left:1px solid var(--border);background:color-mix(in srgb,var(--muted) 30%,var(--card));padding:20px 16px}.live-events{position:relative;min-height:365px;margin-top:12px}.live-events button{display:flex;align-items:center;gap:9px;padding:10px 0;width:100%;text-align:left;border-bottom:1px solid var(--border);min-height:54px}.event-icon{width:28px;height:28px;display:grid;place-items:center;border-radius:8px;background:#edf3ff;color:#779bcd;flex-shrink:0}.event-icon.delivered{background:#e9f6ef;color:#40a17f}.event-icon.returned{background:#fff0eb;color:#d181