und:var(--muted);border-radius:50%}.live-detail-stages li.passed{color:#479c82}.live-detail-stages small{margin-left:auto}@keyframes livePulse{50%{box-shadow:0 0 0 5px #29a98920}}@keyframes livePacket{from{left:0;opacity:0}20%{opacity:1}to{left:100%;opacity:0}}@keyframes regionArrival{0%{background:#ddecff;border-color:#6e9ee5}100%{background:var(--card)}}@media(max-width:1100px){.live-workspace{grid-template-columns:1fr}.live-feed{border-left:0;border-top:1px solid var(--border)}.live-events{min-height:0;display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.live-ops>header{align-items:flex-start;flex-wrap:wrap}.live-metrics{grid-template-columns:repeat(3,1fr)}.live-metrics button{border-bottom:1px solid var(--border)}.live-regions{grid-template-columns:repeat(7,1fr)}}@media(max-width:650px){.live-regions{grid-template-columns:repeat(3,1fr)}.live-events{grid-template-columns:1fr}.live-ops>header{padding:18px}.live-scenarios{padding:0 18px 15px}.live-nodes{gap:2px}.live-node h4{font-size:11px}.live-outcomes{grid-template-columns:1fr}.live-metrics strong{font-size:25px}.live-process{padding:18px}.live-ops h2{font-size:18px}.live-subhead{flex-wrap:wrap}.live-ops>footer{flex-wrap:wrap}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}.dark .live-ops{border-color:var(--border)}.dark .live-ops>header,.dark .live-outcomes>div{background:var(--muted)}
